def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    opp_c = sum(1 for _, o in history if o == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for m, _ in history if m == 'C')
    my_d = n - my_c

    # If opponent has been mostly defecting, defect.
    if opp_d > opp_c and n >= 5:
        return 'D'

    # Recent opponent defections.
    recent_window = min(5, n)
    recent_opp_def = sum(1 for i in range(n - recent_window, n) if history[i][1] == 'D')
    if recent_opp_def >= 4:
        return 'D'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    # Forgiveness rate: how often opponent cooperates after we defect.
    forgive = 0
    retaliate = 0
    for i in range(1, n):
        if history[i-1][0] == 'D':
            if history[i][1] == 'C':
                forgive += 1
            else:
                retaliate += 1
    total_resp = forgive + retaliate
    if total_resp > 0:
        forgiveness_rate = forgive / total_resp
    else:
        forgiveness_rate = 0.5

    # Recent opponent cooperation rate.
    window10 = min(10, n)
    recent_opp_c10 = sum(1 for i in range(n - window10, n) if history[i][1] == 'C')
    recent_opp_rate = recent_opp_c10 / window10

    if opp_last == 'D':
        my_def_last2 = 0
        if n >= 1 and history[-1][0] == 'D':
            my_def_last2 += 1
        if n >= 2 and history[-2][0] == 'D':
            my_def_last2 += 1
        if my_def_last2 > 0:
            # Likely retaliation; forgive to break the cycle.
            if rng.random() < 0.7:
                return 'C'
            else:
                return 'D'
        else:
            # Unprovoked defection; punish.
            return 'D'

    # Opponent cooperated last round.
    p = 0.1
    if forgiveness_rate > 0.7:
        p = 0.45
    elif forgiveness_rate > 0.5:
        p = 0.3
    elif forgiveness_rate < 0.3:
        p = 0.05
    else:
        p = 0.15

    # Against a noisy/moderately forgiving opponent, exploit more.
    if 0.4 < forgiveness_rate < 0.6 and 0.4 < opp_c / n < 0.6:
        p = 0.4

    if recent_opp_rate > 0.9 and opp_c > 5:
        p += 0.15
    if opp_c / n > 0.9:
        p += 0.1

    # If we have been defecting a lot recently, be more cautious.
    recent_my_def = 0
    for i in range(max(0, n - 5), n):
        if history[i][0] == 'D':
            recent_my_def += 1
    if recent_my_def >= 3:
        p *= 0.5

    # Endgame: increase exploitation if opponent is forgiving.
    if n >= 95 and forgiveness_rate > 0.5:
        p += 0.1
    if n >= 97 and forgiveness_rate > 0.5:
        p += 0.2
    if n >= 98 and forgiveness_rate > 0.5:
        p += 0.3

    # Always defect on the final round.
    if n >= 99:
        return 'D'

    if p < 0.0:
        p = 0.0
    if p > 0.8:
        p = 0.8

    if rng.random() < p:
        return 'D'
    else:
        return 'C'
